#include <bits/stdc++.h>
using namespace std;

/*
Interpretation:
Each customer i gives three acceptable time intervals (mod 24) for
breakfast, lunch, supper. We may choose one global serving time for each meal.
A customer is satisfied iff all three chosen times lie in that customer's
corresponding intervals.

We need maximize number of satisfied customers.

Model:
For each meal independently, a customer accepts a subset of hours on a 24-hour
clock. Since intervals may wrap around midnight, represent each meal interval
as a bitmask of 24 possible hours.

For any triple of chosen hours (b,l,s), the number of satisfied customers is
the count of customers whose breakfast mask contains b, lunch mask contains l,
and supper mask contains s.

Brute force over 24^3 = 13824 triples, counting customers each time:
O(n * 24^3), which is fine for typical constraints and very safe in C++.

Input format assumption:
n
b1_start b1_end l1_start l1_end s1_start s1_end
...
for n customers

Each interval is inclusive on integer hours 0..23.
If start <= end, accepted hours are [start, end].
If start > end, it wraps: [start,23] U [0,end].

If your judge uses a different but equivalent format, adapt parsing accordingly.
*/

static inline uint32_t make_mask(int a, int b) {
    uint32_t m = 0;
    if (a <= b) {
        for (int h = a; h <= b; ++h) m |= (1u << h);
    } else {
        for (int h = a; h < 24; ++h) m |= (1u << h);
        for (int h = 0; h <= b; ++h) m |= (1u << h);
    }
    return m;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<uint32_t> B(n), L(n), S(n);
    for (int i = 0; i < n; ++i) {
        int bs, be, ls, le, ss, se;
        cin >> bs >> be >> ls >> le >> ss >> se;
        B[i] = make_mask(bs, be);
        L[i] = make_mask(ls, le);
        S[i] = make_mask(ss, se);
    }

    int ans = 0;
    for (int b = 0; b < 24; ++b) {
        uint32_t bm = (1u << b);
        for (int l = 0; l < 24; ++l) {
            uint32_t lm = (1u << l);
            for (int s = 0; s < 24; ++s) {
                uint32_t sm = (1u << s);
                int cnt = 0;
                for (int i = 0; i < n; ++i) {
                    if ((B[i] & bm) && (L[i] & lm) && (S[i] & sm)) ++cnt;
                }
                ans = max(ans, cnt);
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

