typedef struct {
    int b1, b2;
    int l1, l2;
    int s1, s2;
} Customer;

static int in_cyclic_interval(int t, int a, int b) {
    if (a <= b) return a <= t && t <= b;
    return t >= a || t <= b;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Customer *c = (Customer *)malloc((size_t)n * sizeof(Customer));
    if (!c) return 0;

    for (int i = 0; i < n; ++i) {
        scanf("%d %d %d %d %d %d",
              &c[i].b1, &c[i].b2,
              &c[i].l1, &c[i].l2,
              &c[i].s1, &c[i].s2);
    }

    int best = 0;

    for (int tb = 0; tb < 24; ++tb) {
        for (int tl = 0; tl < 24; ++tl) {
            for (int ts = 0; ts < 24; ++ts) {
                int cnt = 0;
                for (int i = 0; i < n; ++i) {
                    if (in_cyclic_interval(tb, c[i].b1, c[i].b2) &&
                        in_cyclic_interval(tl, c[i].l1, c[i].l2) &&
                        in_cyclic_interval(ts, c[i].s1, c[i].s2)) {
                        ++cnt;
                    }
                }
                if (cnt > best) best = cnt;
            }
        }
    }

    printf("%d\n", best);

    free(c);
    return 0;
}

