import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        // Each customer gives 3 offsets (or "time zones") for breakfast, lunch, supper.
        // We can choose one global serving time shift t.
        // A customer can enjoy all three meals iff their three values are equal,
        // because the same global serving schedule must match all three.
        //
        // So the task reduces to counting, for each value x, how many customers have
        // breakfast=x, lunch=x, supper=x, and taking the maximum over x.
        //
        // If the original statement intended arbitrary integer labels for time zones,
        // this logic matches the standard interpretation of maximizing customers who
        // can be served all three meals with one chosen schedule.

        HashMap<String, Integer> map = new HashMap<>();
        int ans = 0;

        for (int i = 0; i < n; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            int c = fs.nextInt();
            if (a == b && b == c) {
                String key = Integer.toString(a);
                int cnt = map.getOrDefault(key, 0) + 1;
                map.put(key, cnt);
                if (cnt > ans) ans = cnt;
            }
        }

        System.out.println(ans);
    }
}

