class SegTree:
    def __init__(self, n):
        self.N = 1
        while self.N < n:
            self.N <<= 1
        self.data = [0]*(2*self.N)
        self.lazy = [0]*(2*self.N)

    def _apply(self, idx, val):
        self.data[idx] += val
        self.lazy[idx] += val

    def _push(self, idx):
        if self.lazy[idx]:
            self._apply(idx*2, self.lazy[idx])
            self._apply(idx*2+1, self.lazy[idx])
            self.lazy[idx] = 0

    def _range_add(self, l, r, val, idx, lb, ub):
        if r <= lb or ub <= l:
            return
        if l <= lb and ub <= r:
            self._apply(idx, val)
            return
        self._push(idx)
        mid = (lb+ub)//2
        self._range_add(l, r, val, idx*2, lb, mid)
        self._range_add(l, r, val, idx*2+1, mid, ub)
        self.data[idx] = max(self.data[idx*2], self.data[idx*2+1])

    def range_add(self, l, r, val):
        self._range_add(l, r, val, 1, 0, self.N)

    def query_max(self):
        return self.data[1]

def solve():
    n = int(input())
    customers = []
    max_time = 0
    for _ in range(n):
        b1,b2,l1,l2,s1,s2 = map(int, input().split())
        customers.append((b1,b2,l1,l2,s1,s2))
        max_time = max(max_time, b2, l2, s2)

    max_time += 2  # safety
    events = [[] for _ in range(max_time+2)]
    for idx, (b1,b2,l1,l2,s1,s2) in enumerate(customers):
        events[b1].append((1, idx, l1, l2, s1, s2))
        events[b2+1].append((-1, idx, l1, l2, s1, s2))

    seg = SegTree(max_time+2)
    active_lunches = [[] for _ in range(max_time+2)]
    active_suppers = [[] for _ in range(max_time+2)]

    ans = 0
    for b in range(max_time+1):
        for typ, idx, l1, l2, s1, s2 in events[b]:
            if typ == 1:
                active_lunches[l1].append((1, idx, s1, s2))
                active_lunches[l2+1].append((-1, idx, s1, s2))
            else:
                active_lunches[l1].append((-1, idx, s1, s2))
                active_lunches[l2+1].append((1, idx, s1, s2))

        # sweep lunch time
        for l in range(max_time+1):
            for typ, idx, s1, s2 in active_lunches[l]:
                seg.range_add(s1, s2+1, typ)
            # after updating, we can query max supper coverage
            cur = seg.query_max()
            ans = max(ans, cur)

    print(ans)

if __name__ == "__main__":
    solve()
